from copy import deepcopy


def grade_responses(items, responses):
    if not isinstance(items, list) or not isinstance(responses, list):
        raise TypeError("items and responses must be lists")
    if len(items) != len(responses):
        raise ValueError("response count mismatch")
    for item in items:
        if not isinstance(item, dict) or set(item) != {"prompt", "expected"}:
            raise ValueError("invalid item")
        if not isinstance(item["prompt"], str) or not item["prompt"]:
            raise ValueError("invalid prompt")
    result = []
    score = 0
    for item, response in zip(items, responses):
        correct = response == item["expected"]
        score += int(correct)
        result.append({"prompt": item["prompt"], "response": deepcopy(response), "correct": correct})
        if not correct:
            break
    return {"score": score, "total": len(items), "details": result}
```

